    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def runs_on_edge(row_index):
        row = grid[row_index]
        runs = []
        c = 0
        while c < w:
            end = c + 1
            while end < w and row[end] == row[c]:
                end += 1
            if row[c] != background and end - c >= 2:
                runs.append((c, end, row[c]))
            c = end
        return runs

    top_runs = runs_on_edge(0)
    bottom_runs = runs_on_edge(h - 1)
    if not top_runs or not bottom_runs:
        return out

    pairs = [
        (t, b) for t in top_runs for b in bottom_runs
        if t[2] == b[2]
    ]
    if pairs:
        top, bottom = max(
            pairs,
            key=lambda p: (min(p[0][1] - p[0][0], p[1][1] - p[1][0]),
                           p[0][1] - p[0][0] + p[1][1] - p[1][0])
        )
    else:
        top = max(top_runs, key=lambda run: run[1] - run[0])
        bottom = max(bottom_runs, key=lambda run: run[1] - run[0])

    border = {(0, c) for c in range(top[0], top[1])}
    border.update((h - 1, c) for c in range(bottom[0], bottom[1]))

    markers = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != background and (r, c) not in border
    ]
    if not markers:
        return out

    color_counts = {}
    for _, _, color in markers:
        color_counts[color] = color_counts.get(color, 0) + 1
    fill = max(color_counts, key=color_counts.get)
    marker_cells = {(r, c) for r, c, color in markers if color == fill}

    offsets = set()
    for _, c in marker_cells:
        if top[0] <= c < top[1]:
            offsets.add(c - top[0])
        if bottom[0] <= c < bottom[1]:
            offsets.add(c - bottom[0])

    if not offsets:
        return out

    top_lanes = [top[0] + offset for offset in offsets
                 if top[0] + offset < top[1]]
